# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
L, A, V, P, T, R, MA, PA, N, K = "Lucas", "Amparo", "Vicente", "Pepe", "Toni", "Ramón", "Maribel", "Paco", "Nuria", "Min-seo"
D = [
("#", "Escena 1 · 20:30 · Bar de la plaza, Onda", "장면 1 · 저녁 8시 30분 · 온다, 광장의 바"),
(None, "Jueves 26 de marzo. El bar de la plaza está lleno hasta la puerta: ochenta personas de la fábrica, con sus parejas y algún niño. En la barra, cazuelas de titaina, all i pebre, coca de tomate y patatas bravas. Alguien ha colgado detrás de la barra un papel escrito a mano: «Riad: lote 1 + ½».", "3월 26일 목요일. 광장의 바가 문 앞까지 꽉 찼다. 공장 사람 80명이 배우자와 아이 몇과 함께 와 있다. 바 위에는 티타이나, 알리페브레, 토마토 코카, 파타타스 브라바스가 담긴 냄비들. 누군가 바 뒤에 손으로 쓴 종이를 붙여 놓았다. '리야드: 1로트 + ½'."),
(T, "¡Lucas! ¡Por fin! Te he guardado sitio. Aquí, al lado de la titaina, que es lo primero que se acaba.", "루카스! 드디어! 자리 맡아 놨어. 여기, 티타이나 옆에. 그게 제일 먼저 떨어지거든."),
(L, "Gracias, Toni. ¿Quién ha escrito lo del papel?", "고마워요, 토니. 저 종이는 누가 쓴 거예요?"),
(T, "Yo. ¿A que queda bien? «Uno más medio». Mi nieto me ha enseñado a hacer la fracción.", "나. 괜찮지? '1 더하기 반.' 손자가 분수 쓰는 법 가르쳐 줬어."),
(L, "Queda perfecto. Mejor que el correo de Riad.", "완벽해요. 리야드에서 온 메일보다 나아요."),
(PA, "¡Lucas! Enhorabuena, hombre. Bueno, enhorabuena a todos.", "루카스! 축하해요. 아니, 모두 축하해요."),
(L, "Gracias, Paco. Pero las felicidades son para vosotros. Yo solo he viajado. Los hornos los habéis llevado vosotros.", "고마워요, 파코. 하지만 축하는 여러분 몫이에요. 저는 출장만 다녔어요. 가마를 지킨 건 여러분이죠."),
(PA, "Eso díselo a mi mujer, que dice que ya no me ve el pelo.", "그건 우리 집사람한테 말해 줘요. 요즘 내 얼굴을 못 본다고 하니까."),
(MA, "Y a la mía, que dice que hablo de tonos en sueños.", "우리 집 사람한테도요. 내가 잠꼬대로 색조 얘기를 한대요."),
(N, "Yo he soñado en árabe. Bueno, con letras árabes. Tres noches seguidas, por la baldosa de Tariq.", "난 아랍어로 꿈꿨어요. 아니, 아랍 문자로요. 타리크 타일 때문에 사흘 밤 연속."),
(L, "Nuria, por cierto: Tariq dice que una letra va un poco más arriba. Pero me pidió que no te lo dijera.", "누리아, 그건 그렇고 타리크가 글자 하나가 조금 더 위로 가야 한대요. 근데 당신한테는 말하지 말아 달라고 했어요."),
(N, "¿Y me lo dices?", "그런데 말하는 거예요?"),
(L, "Te lo digo porque la próxima la vas a hacer perfecta.", "다음 건 완벽하게 만들 테니까 말하는 거예요."),
(N, "Eso es chantaje emocional. Pero acepto. La próxima, con un calígrafo de verdad.", "그건 감정적 협박이에요. 하지만 받아들일게요. 다음엔 진짜 서예가랑 할게요."),
(MA, "Lucas, una pregunta seria en una noche de fiesta: ¿los saudíes miden el tono con nuestros patrones o con los suyos?", "루카스, 잔칫날 밤에 진지한 질문 하나요. 사우디는 색조를 우리 기준으로 재요, 자기네 기준으로 재요?"),
(L, "Con los nuestros, si Noura los aprueba. Te manda saludos, por cierto. Dice que tu laboratorio es el más ordenado que ha visto.", "누라가 승인하면 우리 기준으로요. 그건 그렇고 안부 전하래요. 당신 실험실이 자기가 본 것 중에 제일 정리가 잘돼 있대요."),
(MA, "(se pone colorada) Eso, mañana, lo cuelgo en la puerta del laboratorio.", "(얼굴이 빨개지며) 그 말, 내일 실험실 문에 붙여 놓을래요."),
(PA, "Y yo cuelgo la lista de los veintiuno. Mañana firman los contratos fijos.", "난 21명 명단 붙일게요. 내일 정규직 계약서에 서명해요."),
(None, "Ramón se abre paso entre la gente con un plato de all i pebre en una mano y el móvil en la otra.", "라몬이 한 손엔 알리페브레 접시, 다른 손엔 휴대폰을 들고 사람들 사이를 헤치고 온다."),
(R, "Lucas, la señora Navarro ya ha firmado el aval definitivo. Me ha llamado hace una hora. Y me ha dicho que nos felicitara de su parte.", "루카스, 나바로 씨가 이행 보증에 벌써 서명했어. 한 시간 전에 전화 왔어. 자기 대신 우리를 축하해 달래."),
(L, "¿El banco nos felicita? Eso es nuevo.", "은행이 우리를 축하한다고요? 처음 듣는 일이네요."),
(R, "El banco felicita a los que pagan. Llevamos dos años pagando todo a tiempo. Eso también es un mérito.", "은행은 돈 갚는 사람을 축하해. 우리 2년째 전부 제때 갚고 있거든. 그것도 공로야."),
(A, "Ramón, deja el móvil. Hoy no hay números.", "라몬, 휴대폰 내려놔요. 오늘은 숫자 없기."),
(R, "Hoy hay un número: ochenta raciones de titaina. Y ya han caído sesenta.", "오늘 숫자 하나 있어. 티타이나 80인분. 벌써 60인분 없어졌어."),
(A, "Pues que traigan más. Invita la casa, lo ha dicho mi padre.", "그럼 더 가져오라고 해요. 회사가 쏜다고 아빠가 그랬잖아요."),
(R, "Tu padre lo ha dicho. El presupuesto no.", "네 아빠가 말했지. 예산은 안 했어."),
(T, "Ramón, que hoy es fiesta. ¡Que se apunte en la cuenta del desierto!", "라몬, 오늘은 잔칫날이에요. 사막 계정에 달아 두라고 해요!"),
(None, "Vicente se sube a una silla. Alguien golpea un vaso con un tenedor. Poco a poco, el bar se calla.", "비센테가 의자 위에 올라선다. 누군가 포크로 잔을 두드린다. 조금씩 바가 조용해진다."),
(V, "Bueno, bueno. No os asustéis, que no voy a hablar mucho. Mi mujer me ha dado tres minutos.", "자, 자. 겁먹지 마, 길게 말 안 할 테니까. 집사람이 3분 줬어."),
(T, "¡Dos y medio, don Vicente!", "2분 반이요, 사장님!"),
(V, "Dos y medio. Hace catorce meses, esta fábrica tenía un horno parado, cuarenta mil metros en el almacén y una chincheta en el mapa. Bueno, dos: Francia y Portugal.", "2분 반. 14개월 전에 이 공장엔 멈춘 가마 하나, 창고에 40만 제곱미터, 지도에 압정 하나가 있었어. 아니, 두 개구나. 프랑스랑 포르투갈."),
(P, "¡Cuatrocientos mil, Vicente! ¡Cuatrocientos mil metros!", "40만이요, 비센테! 40만 제곱미터!"),
(V, "Cuatrocientos mil. Gracias, Pepe. Ya veis que hasta en las fiestas me corrige. (risas) Y hoy tenemos dos hornos encendidos y el tercero en el quirófano. Y el mapa del despacho de exportación parece un erizo.", "40만. 고마워, 페페. 잔치에서도 날 고쳐 주는 거 봤지. (웃음) 그리고 오늘 우린 가마 두 개에 불이 켜졌고 세 번째는 수술실에 있어. 수출팀 사무실 지도는 고슴도치 같고."),
(T, "(desde la barra) ¡Un erizo con pinchos de colores!", "(바 쪽에서) 알록달록한 가시 달린 고슴도치요!"),
(V, "Quién nos iba a decir, en 2009, que algún día venderíamos baldosas en el desierto. Yo no lo creí. Lo creyó un madrileño que no sabía lo que era un atomizador.", "2009년에 우리가 언젠가 사막에 타일을 팔게 될 거라고 누가 상상이나 했겠어. 난 안 믿었어. 분무건조기가 뭔지도 모르던 마드리드 사람이 믿었지."),
(L, "(desde abajo) ¡Ahora ya lo sé!", "(아래에서) 이젠 알아요!"),
(V, "Ahora ya lo sabe. Y lo creyó mi hija, que no se cree nada de nadie.", "이젠 알지. 그리고 누구 말도 안 믿는 내 딸이 믿었고."),
(A, "¡Papá!", "아빠!"),
(V, "Y lo hicieron posible ochenta personas que han trabajado como nunca. Así que, por los tres hornos, por los que vuelven y por los que llegan. ¡Salud!", "그리고 그걸 해낸 건 그 어느 때보다 열심히 일한 80명이야. 그러니까 가마 세 개를 위해, 돌아온 사람들과 새로 오는 사람들을 위해. 건배!"),
(None, "«¡Salud!». Vasos en alto. Alguien grita «¡Que hable Pepe!». El grito se repite por todo el bar.", "'건배!' 잔들이 높이 오른다. 누군가 '페페도 한마디 해요!' 하고 외친다. 그 외침이 바 전체로 퍼진다."),
(P, "Yo no hablo. Yo hago baldosas.", "난 말 안 해. 난 타일 만들어."),
(T, "¡Venga, Pepe, que lo dice todo el mundo!", "에이, 페페, 다들 그러잖아요!"),
(P, "(se levanta sin subirse a la silla) Vale. Una cosa. Hace cuarenta años, cuando entré, el abuelo de Vicente me dijo: «Un horno no se hace en tres semanas». Yo se lo repetí a Lucas en septiembre. Y tenía razón: no se hace en tres semanas.", "(의자에 올라가지 않고 일어서며) 좋아. 하나만. 40년 전에 내가 들어왔을 때 비센테 할아버지가 그랬어. '가마는 3주 만에 못 만든다.' 그걸 9월에 루카스한테 똑같이 말했지. 그리고 내 말이 맞았어. 3주 만에는 안 돼."),
(T, "¿Y en cuánto se hace, Pepe?", "그럼 몇 주 걸려요, 페페?"),
(P, "En seis. Empezó el lunes, con veinte personas que no van a dormir mucho. Así que el brindis es para los rodillos nuevos. Y para los que los van a montar.", "6주. 월요일에 시작했어. 잠 별로 못 잘 스무 명이랑. 그러니까 건배는 새 롤러를 위해서야. 그리고 그 롤러를 달 사람들을 위해서."),
(None, "Aplausos. Pepe se sienta enseguida y se mete una cucharada de titaina en la boca, como si no hubiera dicho nada.", "박수. 페페는 곧바로 앉아 아무 말도 안 한 사람처럼 티타이나 한 숟가락을 입에 넣는다."),
(A, "(a Lucas, en voz baja) Es la primera vez que le oigo hacer un discurso.", "(루카스에게 작은 소리로) 페페가 연설하는 거 처음 들어 봐요."),
(L, "Dos frases. Para Pepe, eso es un discurso de investidura.", "두 문장이요. 페페한테 그건 취임 연설급이죠."),
(A, "Ve a decírselo. A Pepe no le gustan los aplausos, pero las palabras de una en una, sí.", "가서 말해 줘요. 페페는 박수는 싫어해도 한 사람씩 하는 말은 좋아해요."),
(None, "Lucas se acerca a Pepe, que come solo en una esquina de la barra.", "루카스가 바 한쪽 구석에서 혼자 먹고 있는 페페에게 다가간다."),
(L, "Pepe, gracias. Por el horno y por el discurso.", "페페, 고마워요. 가마도, 연설도."),
(P, "No me des las gracias. Dame trabajo para el horno y ya está.", "고맙단 말은 하지 마. 가마에 일감이나 줘, 그럼 됐어."),
(L, "Trabajo no te va a faltar. Lo malo va a ser lo contrario.", "일감은 모자라지 않을 거예요. 문제는 그 반대겠죠."),
(P, "Ya. Eso me temo. (lo mira un momento) ¿Sabes qué? El abuelo de Vicente tampoco sabía lo que era un atomizador cuando empezó. Lo aprendió. Como tú.", "그래. 그게 걱정이야. (잠시 그를 보며) 그거 알아? 비센테 할아버지도 처음엔 분무건조기가 뭔지 몰랐어. 배웠지. 너처럼."),
(L, "Viniendo de ti, eso vale más que el correo de Riad.", "당신한테 그 말 들으니 리야드 메일보다 값지네요."),
(P, "No te emociones. Vete, que te busca el jefe.", "감동하지 마. 가 봐, 대장이 찾는다."),
(V, "(bajando de la silla, a Lucas) Lucas, ¿te puedo pedir un favor? Mañana a primera hora, ¿te vendría bien pasar por mi despacho? Quiero hablar contigo del año que viene.", "(의자에서 내려오며 루카스에게) 루카스, 부탁 하나 해도 될까? 내일 아침 일찍 내 사무실에 들러 줄 수 있겠나? 내년 얘기를 하고 싶어."),
(L, "Claro. ¿Pasa algo?", "물론이죠. 무슨 일 있으세요?"),
(V, "Nada malo. Cosas de viejo. Hoy no. Hoy, titaina.", "나쁜 일은 아니야. 늙은이 일이지. 오늘은 말고. 오늘은 티타이나."),
(R, "Si queda.", "남아 있다면."),
(T, "(desde la barra) ¡Queda, queda! ¡Pero poca!", "(바 쪽에서) 남았어요, 남았어! 근데 조금!"),

("#", "Escena 2 · 22:15 · Despacho de exportación", "장면 2 · 밤 10시 15분 · 수출팀 사무실"),
(None, "La fiesta sigue en la plaza. Lucas y Amparo cruzan la calle hasta la fábrica. Toni, que ha vuelto a su turno, les abre la garita con una sonrisa.", "축하는 광장에서 계속된다. 루카스와 암파로가 길을 건너 공장으로 간다. 근무로 돌아간 토니가 웃으며 경비실 문을 열어 준다."),
(T, "¿A estas horas? ¿Ya os vais a trabajar otra vez?", "이 시간에? 벌써 또 일하러 가요?"),
(A, "Solo cinco minutos, Toni. Tenemos que poner una chincheta.", "5분만요, 토니. 압정 하나 꽂아야 해요."),
(T, "Ah, eso es sagrado. Pasad. Y no os olvidéis de apagar la luz, que luego Ramón me riñe a mí.", "아, 그건 신성한 일이지. 들어가요. 불 끄는 거 잊지 말고. 안 그러면 라몬이 나한테 뭐라 해."),
(None, "En el despacho, el mapa del mundo. Una chincheta roja en Monterrey, dos amarillas en Miami y Texas, una azul en Bogotá. Debajo, cementado en la pared, el trozo de baldosa de 1958.", "사무실에 세계 지도가 있다. 몬테레이에 빨간 압정, 마이애미와 텍사스에 노란 압정 두 개, 보고타에 파란 압정 하나. 그 아래 벽에 1958년 타일 조각이 시멘트로 붙어 있다."),
(A, "¿De qué color la ponemos?", "무슨 색으로 꽂을까요?"),
(L, "Verde. Como la bandera saudí. Y como el uno del horno, que está pintado de verde.", "초록이요. 사우디 국기처럼. 그리고 초록으로 칠해진 1호기 '1' 자처럼."),
(A, "¿Lo pones tú?", "당신이 꽂을래요?"),
(L, "No. La pones tú. Yo puse la de Miami delante de Daniel y tú la pusiste aquí, a escondidas. Esta vez, al revés.", "아니요. 당신이 꽂아요. 마이애미 건 내가 다니엘 앞에서 꽂았고, 당신은 여기서 몰래 꽂았잖아요. 이번엔 반대로."),
(None, "Amparo clava la chincheta verde en Riad. Se quedan los dos mirando el mapa.", "암파로가 리야드에 초록 압정을 꽂는다. 둘은 지도를 바라보며 서 있다."),
(A, "Cuatro países nuevos en catorce meses. Si me lo llegas a decir el día que entraste por esa puerta, te habría echado.", "14개월에 새 나라 넷. 당신이 저 문으로 처음 들어온 날 그 말을 했으면 쫓아냈을 거예요."),
(L, "Me lo dijiste con la mirada. Recuerdo perfectamente: «Si tienes una idea brillante, no tardes un mes».", "눈빛으로 그렇게 말했어요. 정확히 기억해요. '기막힌 아이디어가 있으면 한 달씩 걸리지 마요.'"),
(A, "Y tardaste dos.", "그리고 두 달 걸렸죠."),
(L, "Y llevamos tres países firmados. Bueno, tres firmados y uno a punto de firmar.", "그리고 세 나라에 서명해 놨어요. 아니, 세 나라 서명에 하나는 곧 서명이죠."),
(A, "El seis de abril, en Riad. Ya tengo el billete. De ida y vuelta, esta vez.", "4월 6일, 리야드에서요. 표는 벌써 끊었어요. 이번엔 왕복으로."),
(L, "¿Ida y vuelta? Eso sí que es una novedad.", "왕복이요? 그거야말로 새 소식이네요."),
(A, "Marc tiene una función de teatro el nueve. Si no vuelvo, me mata.", "마르크가 9일에 연극 공연이 있어요. 안 돌아가면 날 죽일 거예요."),
(L, "¿Qué hace en la obra?", "연극에서 뭐 하는데요?"),
(A, "De árbol. Pero dice que es el árbol más importante.", "나무 역이요. 근데 자기가 제일 중요한 나무래요."),
(L, "Como Pepe con los rodillos.", "롤러 얘기하는 페페처럼요."),
(A, "(ríe) Exacto. Oye, ¿qué querrá mi padre mañana?", "(웃으며) 딱 그거예요. 그런데 아빠가 내일 무슨 얘기를 하려는 걸까요?"),
(L, "No lo sé. Ha dicho «cosas de viejo».", "모르겠어요. '늙은이 일'이라던데요."),
(A, "Cuando mi padre dice «cosas de viejo», es que lleva meses pensándolo.", "아빠가 '늙은이 일'이라고 하면 몇 달째 생각해 온 거예요."),
(L, "¿Y tú qué crees que es?", "당신은 뭐라고 생각해요?"),
(A, "No lo sé. Y por primera vez en mucho tiempo, no quiero adivinarlo. Hoy no.", "모르겠어요. 그리고 오랜만에 처음으로 짐작하고 싶지 않아요. 오늘은요."),
(L, "Hoy, titaina.", "오늘은 티타이나."),
(A, "Hoy, titaina. Venga, apaga la luz, que Toni nos riñe.", "오늘은 티타이나. 자, 불 꺼요, 토니가 혼내기 전에."),

("#", "Escena 3 · 22:40 · Despacho de exportación — una llamada de Seúl", "장면 3 · 밤 10시 40분 · 수출팀 사무실 — 서울에서 온 전화"),
(None, "Están a punto de apagar la luz cuando suena el teléfono fijo. En la pantalla, un prefijo que nunca había aparecido en aquel aparato: +82.", "막 불을 끄려는데 유선 전화가 울린다. 화면에는 그 전화기에 한 번도 뜬 적 없는 국가번호가 떠 있다. +82."),
(A, "¿Más ochenta y dos? ¿Eso dónde es?", "+82? 거기가 어디예요?"),
(L, "Corea del Sur. Allí son... las seis y cuarenta de la mañana. (descuelga) Cerámicas Albalat, buenas noches. Le habla Lucas Ferrer.", "한국이요. 거긴 지금… 아침 6시 40분이에요. (수화기를 들며) 세라미카스 알발라트입니다, 안녕하세요. 루카스 페레르입니다."),
(K, "Buenas noches, señor Ferrer. Perdone que le llame a estas horas. Le habla Kim Min-seo, de Seorin Interiores, en Seúl. ¿Le viene bien hablar un momento, o prefiere que le llame mañana?", "안녕하세요, 페레르 씨. 이런 시간에 전화드려 죄송합니다. 서울 서린 인테리어의 김민서입니다. 잠시 통화 괜찮으신가요, 아니면 내일 다시 전화드릴까요?"),
(L, "Me viene perfectamente, señora Kim. Su español es excelente. ¿Dónde lo aprendió?", "아주 괜찮습니다, 김 대표님. 스페인어가 훌륭하시네요. 어디서 배우셨어요?"),
(K, "En Salamanca. Hice allí el máster, hace doce años. Todavía echo de menos la Plaza Mayor a las once de la noche.", "살라망카에서요. 12년 전에 거기서 석사를 했어요. 아직도 밤 11시의 마요르 광장이 그리워요."),
(L, "Entonces somos casi vecinos. ¿En qué puedo ayudarla?", "그럼 거의 이웃이네요. 무엇을 도와드릴까요?"),
(K, "Le seré directa, porque sé que allí es tarde. En diciembre estuve en Monterrey, en un hotel nuevo de San Pedro. El vestíbulo era un mármol blanco con una montaña escondida en la veta.", "늦은 시간이니 바로 말씀드리겠습니다. 12월에 몬테레이 산페드로의 새 호텔에 묵었어요. 로비가 흰 대리석 무늬였는데, 결 속에 산이 숨어 있더군요."),
(L, "El Cerro de la Silla. «Blanco San Pedro». Lo diseñó nuestra diseñadora, Nuria.", "세로 데 라 시야예요. '블랑코 산페드로'. 저희 디자이너 누리아가 디자인했습니다."),
(K, "Eso me dijo la directora del hotel. Desde entonces, he estado siguiéndoles: Monterrey, Miami, y ahora, me han dicho, Riad. Mis felicitaciones, por cierto.", "호텔 지배인도 그렇게 말하더군요. 그 뒤로 계속 지켜봤어요. 몬테레이, 마이애미, 그리고 들리는 말로는 이제 리야드까지. 그건 그렇고, 축하드립니다."),
(L, "(tapa el auricular, a Amparo) Ya sabe lo de Riad. (al teléfono) Muchas gracias. Las noticias vuelan.", "(수화기를 가리고 암파로에게) 리야드 건을 벌써 알아요. (전화에 대고) 정말 감사합니다. 소식이 빠르네요."),
(K, "En nuestro sector, sí. Le explico. Mi empresa importa baldosas y hace interiorismo para constructoras. Una de las grandes, Hanul Construcción, va a lanzar una marca nueva de apartamentos de lujo: «Hanul Lumière».", "저희 업계에선 그렇죠. 설명드릴게요. 저희 회사는 타일을 수입하고 건설사를 위한 인테리어를 합니다. 대형 건설사 중 하나인 한울건설이 새 고급 아파트 브랜드를 출시해요. '한울 뤼미에르'."),
(L, "¿Cuántos apartamentos, aproximadamente?", "대략 몇 세대인가요?"),
(K, "Tres complejos en Seúl y alrededores. Unos dos mil seiscientos apartamentos en dos años. Suelos de salón en gran formato y paredes de baño. Calculamos unos noventa mil metros cuadrados.", "서울과 근교에 단지 세 곳이요. 2년 동안 약 2,600세대. 거실 바닥은 대형 규격, 욕실 벽까지요. 약 9만 제곱미터로 계산하고 있어요."),
(L, "¿Qué formatos piden para los salones?", "거실에는 어떤 규격을 원하나요?"),
(K, "Sesenta por ciento veinte y ochenta por ciento sesenta. Mates o semipulidos, nada demasiado brillante. Y algo muy importante: en Corea el cliente abre la caja y mira cada pieza. El embalaje es parte del producto.", "60×120과 80×160이요. 무광이나 반광, 너무 반짝이는 건 안 돼요. 그리고 아주 중요한 것: 한국에선 고객이 상자를 열고 한 장 한 장 봐요. 포장도 제품의 일부예요."),
(A, "(en voz baja) Cantoneras otra vez.", "(작은 소리로) 또 모서리 보호대네."),
(L, "(escribe la cifra en un papel y se la enseña a Amparo) Noventa mil metros cuadrados. ¿Me lo puede repetir, por favor?", "(종이에 숫자를 적어 암파로에게 보여 주며) 9만 제곱미터요. 다시 한번 말씀해 주시겠어요?"),
(K, "Noventa mil. Y quisiera proponerles algo más: la distribución exclusiva de Cerámicas Albalat en Corea, durante cinco años. Las constructoras coreanas quieren un proveedor europeo con una historia. Ustedes tienen una.", "9만이요. 그리고 하나 더 제안드리고 싶어요. 한국에서 세라미카스 알발라트의 5년 독점 유통권이요. 한국 건설사들은 이야기가 있는 유럽 공급업체를 원해요. 귀사엔 그게 있고요."),
(L, "Es una propuesta muy seria, señora Kim. Le agradezco mucho la confianza. ¿Sería tan amable de enviarme por escrito lo que me acaba de contar?", "아주 진지한 제안이네요, 김 대표님. 믿어 주셔서 정말 감사합니다. 방금 말씀하신 내용을 서면으로 보내 주시겠습니까?"),
(K, "Ya lo tiene en su correo. Se lo he enviado antes de llamar. En Corea decimos «ppalli, ppalli»: rápido, rápido.", "이미 메일함에 있을 거예요. 전화하기 전에 보냈어요. 한국에선 '빨리빨리'라고 하죠. 빨리, 빨리."),
(L, "¿Puedo preguntarle quién le dio nuestro contacto directo?", "누가 저희 직통 연락처를 드렸는지 여쭤봐도 될까요?"),
(K, "La oficina comercial de España en Seúl. Y una consultora del ICEX, Marta Ortiz, que habla muy bien de ustedes.", "서울의 스페인 무역관이요. 그리고 ICEX 컨설턴트 마르타 오르티스 씨가요. 두 분을 아주 좋게 말하더군요."),
(L, "(abre el correo en el ordenador) Aquí está. Con planos y todo. Usted no pierde el tiempo.", "(컴퓨터로 메일을 열며) 여기 있네요. 도면까지. 시간을 낭비하지 않으시는군요."),
(K, "En la construcción coreana, el tiempo es lo más caro. Hanul quiere elegir proveedor antes de mayo. Por eso le llamo ahora, y no la semana que viene.", "한국 건설에선 시간이 제일 비싸요. 한울은 5월 전에 공급업체를 정하고 싶어 해요. 그래서 다음 주가 아니라 지금 전화드리는 거예요."),
(L, "Lo entiendo. Antes de responderle, tengo que hablarlo con mi socia. Está aquí a mi lado, de hecho.", "이해합니다. 답변드리기 전에 제 동업자와 얘기해야 합니다. 사실 바로 옆에 있어요."),
(K, "¿La señora Albalat? La de Monterrey, ¿verdad? La directora del hotel me habló de ella también: «la ingeniera de las cantoneras».", "알발라트 씨요? 몬테레이의 그분 맞죠? 호텔 지배인이 그분 얘기도 했어요. '모서리 보호대 엔지니어.'"),
(A, "(se acerca al teléfono) Buenas noches, señora Kim. Bueno, buenos días. Sí, soy yo. La de las cantoneras.", "(전화기에 다가가며) 안녕하세요, 김 대표님. 아니, 좋은 아침이네요. 네, 저예요. 모서리 보호대 그 사람."),
(K, "Encantada, señora Albalat. Me alegra mucho que esté usted también. Lo que voy a pedirles es para los dos.", "반갑습니다, 알발라트 씨. 함께 계셔서 정말 기쁘네요. 지금 부탁드리려는 건 두 분 모두에게 드리는 거예요."),
(A, "La escuchamos.", "듣고 있습니다."),
(K, "Hanul presenta la marca a los arquitectos el día dos de abril, en Seúl. Si ustedes estuvieran allí, con muestras, tendrían una ventaja que no tiene nadie.", "한울이 4월 2일 서울에서 건축가들에게 브랜드를 발표해요. 그 자리에 두 분이 샘플을 들고 계시면 누구에게도 없는 우위를 갖게 되실 거예요."),
(L, "¿El dos de abril? Eso es... el jueves de la semana que viene.", "4월 2일이요? 그건… 다음 주 목요일이네요."),
(A, "(en voz baja, a Lucas) Y el seis firmamos en Riad.", "(루카스에게 작은 소리로) 그리고 6일엔 리야드에서 서명해요."),
(L, "(en voz baja) Seúl, Riad... Seúl está de camino. Más o menos.", "(작은 소리로) 서울, 리야드… 서울이 가는 길이에요. 대충은."),
(A, "(en voz baja) Más o menos son once horas de avión.", "(작은 소리로) 대충이 비행기로 11시간이에요."),
(K, "Sé que es muy precipitado. Lo siento. Pero en mi experiencia, las mejores oportunidades llegan sin avisar.", "아주 급하다는 거 알아요. 죄송해요. 하지만 제 경험상 가장 좋은 기회는 예고 없이 와요."),
(L, "Eso también nos lo ha enseñado este año, señora Kim. Mañana hablo con nuestro presidente y le respondo antes de que allí acabe el día.", "그건 올해 저희도 배웠습니다, 김 대표님. 내일 대표님과 얘기하고, 거기 하루가 끝나기 전에 답변드리겠습니다."),
(K, "Se lo agradezco. Y, señor Ferrer, una última cosa.", "감사합니다. 그리고 페레르 씨, 마지막으로 하나만요."),
(L, "Dígame.", "말씀하세요."),
(K, "¿Podría venir a Seúl? La semana que viene.", "서울에 와 주실 수 있나요? 다음 주에요."),
(None, "Lucas mira a Amparo. Amparo mira el mapa. En la mesa, el papel con la cifra: 90.000. Fuera, desde la plaza, todavía se oye a la gente cantar.", "루카스가 암파로를 본다. 암파로는 지도를 본다. 책상 위에는 숫자가 적힌 종이가 놓여 있다. 90,000. 밖에서는 광장 사람들의 노랫소리가 아직 들린다."),
(L, "(tapa el auricular) Dice que si podemos ir a Seúl. La semana que viene.", "(수화기를 가리며) 서울에 올 수 있냐고 하네요. 다음 주에."),
(A, "(despacio, saca del cajón una chincheta de un color que todavía no han usado) Dile que mañana le contestamos. Los dos.", "(천천히, 서랍에서 아직 한 번도 안 쓴 색의 압정을 꺼내며) 내일 답하겠다고 전해요. 우리 둘이서."),
]

PRE = [
("text", "장면 미리보기", "대화문을 읽기 전에 줄거리를 확인하고, 아래 질문의 답을 찾으며 읽어 보세요.", [
 "리야드 낙찰을 축하하는 목요일 밤. 광장의 바에 공장 사람 80명이 모여 티타이나를 나눈다. 비센테는 의자 위에서 14개월을 돌아보고, 말이 없는 페페가 생애 첫 '연설'을 한다. 비센테는 루카스에게 '내일 아침 할 얘기가 있다'고 조용히 말한다. 밤 10시가 넘어 루카스와 암파로는 사무실로 가서 지도의 리야드에 초록 압정을 꽂는다. 불을 끄려는 순간 +82로 시작하는 전화가 울린다. 살라망카에서 공부한 서울의 김민서가 큰 제안을 들고 왔다.",
 "듣기 질문 ① 비센테의 건배사에 나오는 '14개월 전'과 '오늘'은 어떻게 다른가? 페페는 무엇을 위해 건배하는가?",
 "듣기 질문 ② 지도에는 어떤 색 압정이 어디에 꽂혀 있는가? 리야드에는 왜 초록을 고르는가? 암파로는 왜 이번엔 왕복표를 샀는가?",
 "듣기 질문 ③ 김민서는 Albalat를 어떻게 알게 되었나? 그녀의 제안(물량·기간·독점)은 무엇이고, 왜 '다음 주'인가?",
]),
]

